{
  "name": "@builtwithtofu/skillful",
  "version": "0.1.0",
  "description": "Author agent skills once, render them per harness",
  "type": "module",
  "files": [
    "cli",
    "harnesses",
    "templates",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "bun build --compile cli/main.ts --outfile dist/skillful",
    "test": "bun test cli",
    "typecheck": "tsc -p tsconfig.json"
  },
  "dependencies": {
    "commander": "15.0.0",
    "yaml": "2.8.2"
  },
  "engines": {
    "bun": ">=1.3.0"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/builtwithtofu/skillful.git"
  },
  "devDependencies": {
    "@types/bun": "1.3.14",
    "typescript": "7.0.2"
  }
}

{
  "name": "opencode",
  "installPaths": {
    "home": { "skills": ".config/opencode/skills", "commands": ".config/opencode/commands", "rules": ".config/opencode/AGENTS.md" },
    "project": { "skills": ".opencode/skills", "commands": ".opencode/commands" }
  },
  "argSyntax": "$ARGUMENTS",
  "skillFrontmatter": ["name", "description", "license", "compatibility", "metadata"],
  "commandFrontmatter": ["description"],
  "commandMerge": "file"
}

